('text-mask','broll-text','MAKE IT MATTER.','Masked poster type, offset print and registration.','ink'),
('text-tempo','broll-text','TYPE HAS TEMPO.','Alternating scale and direction; a folded type ribbon.','acid'),
('mg-orbit','motion-graphic','IDEA → SYSTEM.','Stage the relationship, then reveal six connected nodes.','paper'),
('mg-flow','motion-graphic','ONE FLOW. MANY ROUTES.','Draw a single branching relation with a travelling signal.','blue'),
('wb-flow','whiteboard','THINK IT THROUGH.','Authored pen order with the marker attached to the current stroke.','paper'),
('wb-loop','whiteboard','IDEAS CONNECT.','A feedback loop closes around a handwritten concept.','paper'),
('stop-fan','stop-motion','FOLD A POSSIBILITY.','Paper leaves hinge open on twos; hard contact shadows.','pink'),
('stop-envelope','stop-motion','SEND THE IDEA.','Envelope card, flap and folded plane on held two-frame poses.','paper'),
('vox-detail','vox','FOLLOW THE DETAIL.','Illustrative document, stepped push, one highlight, then a hold.','paper'),
('vox-timeline','vox','SEE THE CONNECTION.','Four illustrative editorial cards linked by a red pen line.','ink'),
