def art(name,family,asset,x,y,w,h=None,cls='',extra=''):
    src=R/'vendor/asset-lib/artwork/atelier'/family/f'{asset}.svg'
    if not src.exists():src=P/'assets/artwork'/family/f'{asset}.svg'
    svg=src.read_text().replace('role="img"','role="img" data-layout-allow-overflow data-layout-allow-overlap'); prefix=name+'-'
    for a in re.findall(r'id="([^"]+)"',svg):svg=svg.replace(f'id="{a}"',f'id="{prefix+a}"').replace(f'url(#{a})',f'url(#{prefix+a})')
    return f'<div class="art {cls}" data-art="{name}" data-layout-allow-overflow data-layout-allow-overlap data-layout-allow-occlusion style="left:{x}px;top:{y}px;width:{w}px;height:{h or w*.75}px" {extra}>{svg}</div>'

def title(words,x=85,y=208,size=165,cls='',width=850):
    return f'<div class="headline sk-display {cls}" style="left:{x}px;top:{y}px;font-size:{size}px;width:{width}px">'+''.join(f'<div class="mask"><span class="word">{s}</span></div>' for s in words)+'</div>'

def label(text,x,y,w=700,cls='',size=29):
    font=cls if cls.startswith('sk-') else 'sk-mono '+cls
    return f'<div class="label {font}" style="left:{x}px;top:{y}px;width:{w}px;font-size:{size}px">{text}</div>'

def placeholder(x,y,s=1):
    return f'<div class="speaker" data-layout-allow-overlap style="left:{x}px;top:{y}px;transform:scale({s});transform-origin:bottom center"><svg viewBox="0 0 420 700" width="420" height="700"><circle cx="210" cy="145" r="88" fill="#171918" stroke="#f1eee5" stroke-width="13"/><path d="M59 700V386Q59 253 210 253Q361 253 361 386V700Z" fill="#171918" stroke="#f1eee5" stroke-width="13"/></svg><div class="speaker-note sk-mono">SPEAKER SLOT</div></div>'

