anim['material']="""words(t,.1,.35,'mask');const light=E(t,.6,2.8);move(a('ribbon'),{r:-18+28*E(t,.2,3),s:.65+.35*E(t,.2,1.1),o:E(t,.2,.1)});move(part('ribbon','highlight'),{x:-26+52*light,y:10-20*light,o:.3+.6*Math.sin(Math.PI*light)});move(a('prism'),{y:280*(1-E(t,1.6,.7)),r:12*E(t,1.6,.7),o:E(t,1.6,.1)});part('prism','left').style.filter='brightness('+(1.15-.3*light)+')';part('prism','right').style.filter='brightness('+(.8+.4*light)+')';part('prism','edge').style.opacity=.4+.5*light;move(a('star'),{r:120*E(t,.8,2.7),s:.1+.9*spring(t,.8),o:E(t,.8,.1)});move(part('star','extrusion'),{x:-5+10*light,y:4-8*light});part('star','bevel').style.opacity=.35+.6*light;"""
