base='''#root{position:absolute;inset:0;width:1920px;height:1080px}.fill{position:absolute;inset:0}.grid{position:absolute;inset:75px;background-image:linear-gradient(currentColor 1px,transparent 1px),linear-gradient(90deg,currentColor 1px,transparent 1px);background-size:160px 160px;opacity:.055}.art{position:absolute;transform-origin:50% 50%}.art svg{display:block;width:100%;height:100%;overflow:visible}.headline{position:absolute;line-height:.98;letter-spacing:-.055em;z-index:3}.mask{overflow:hidden;padding:.12em .04em .15em .01em;margin:-.08em -.04em -.11em -.01em}.word{display:block;transform-origin:left center;white-space:nowrap}.label{position:absolute;line-height:1.2;z-index:3}.label.sk-hand{line-height:1}.topbar,.bottom{position:absolute;left:82px;right:82px;display:flex;justify-content:space-between;align-items:center;font-size:23px;z-index:10}.topbar{top:64px}.bottom{bottom:55px;font-size:21px}.topbar .pill{border:1px solid currentColor;padding:8px 14px;border-radius:28px;font-size:20px}.meter{display:flex;gap:8px}.meter i{width:34px;height:5px;background:currentColor;opacity:.2}.rule{position:absolute;left:82px;right:82px;bottom:100px;height:2px;background:currentColor;transform-origin:left}.cross{position:absolute;width:24px;height:24px;z-index:10}.cross:before,.cross:after{content:'';position:absolute;background:currentColor}.cross:before{left:0;top:11px;width:24px;height:2px}.cross:after{left:11px;top:0;width:2px;height:24px}.view{position:absolute;inset:0;perspective:1200px;perspective-origin:960px 540px}.world{position:absolute;inset:0;transform-style:preserve-3d}.plane{position:absolute;inset:0;width:1920px;height:1080px;backface-visibility:hidden;transform-style:preserve-3d}.speaker{position:absolute;z-index:4}.speaker-note{position:absolute;left:45px;top:469px;width:330px;text-align:center;font-size:24px;color:#f1eee5}
'''
helpers='''const q=s=>root.querySelector(s),qa=s=>Array.from(root.querySelectorAll(s));const a=n=>q('[data-art="'+n+'"]');const part=(n,p)=>a(n).querySelector('[data-part="'+p+'"]');const parts=(n,p)=>p.includes(' ')?Array.from(a(n).querySelectorAll('[data-part="'+p.split(' ')[0]+'"] '+p.split(' ')[1])):Array.from(a(n).querySelectorAll('[data-part^="'+p+'"]'));const E=(t,at,d)=>M.eo(M.clamp((t-at)/d));const spring=(t,at)=>t<at?0:M.S(t-at,18,.72);
function move(el,p){el.style.transform='translate('+(p.x||0)+'px,'+(p.y||0)+'px) rotate('+(p.r||0)+'deg) scale('+(p.s??1)+')';if(p.o!=null)el.style.opacity=p.o;}
function originMove(el,p,x,y){el.style.transformOrigin=x+'px '+y+'px';move(el,p);}
function piece(el,p,seed,t){SK.piece(el,p,seed,t,{amp:1.1});}
function words(t,at,stagger,kind){qa('.word').forEach((el,i)=>SK.enter(el,t-(at+i*stagger),kind));}
function pen(tip,x,y,w){const el=q('.pen');if(!el)return;el.style.opacity=tip?1:0;if(tip)move(el,{x:x+tip.x*w/800-33,y:y+tip.y*w/800-128,r:tip.angle-70});}
'''
pal={'ink':('#171918','#f1eee5'),'paper':('#f1eee5','#171918'),'blue':('#244bff','#f1eee5'),'pink':('#b6a3ef','#171918'),'acid':('#d9fc59','#171918')}
for i,r in enumerate(rows):
    key=r['key'];cid=r['id'];bg,fg=pal[r['theme']]
    furniture=f'<div class="grid" aria-hidden="true"></div><div class="topbar sk-mono"><span>ATELIER / RICHER BY DESIGN</span><span class="pill">{r["style"].upper()}</span></div><div class="bottom sk-mono"><span>{i+1:02} / 16 — MOTION STUDY</span><div class="meter">'+''.join('<i></i>' for _ in range(8))+'</div><span>ORIGINAL / 2026</span></div><div class="rule"></div>'+''.join(f'<div class="cross" style="{pos}" aria-hidden="true"></div>' for pos in ['left:42px;top:39px','right:42px;top:39px','left:42px;bottom:32px','right:42px;bottom:32px'])
    setup=''
    if key=='mg-flow':
        setup="const traveler=document.createElementNS('http://www.w3.org/2000/svg','circle');traveler.setAttribute('r','11');traveler.setAttribute('fill','#fa593d');a('flow').querySelector('svg').appendChild(traveler);"
    if key.startswith('wb-'):
        setup="const ink=[];let at=.4;parts('sketch','stroke-').forEach(group=>group.querySelectorAll('path').forEach(el=>{const dur=SK.len(el)/"+('1600' if key=='wb-flow' else '900')+";ink.push({el,at,dur});at+=dur+.065;}));"
    if key.startswith('px-'):
        setup="qa('.plane').forEach(el=>{const z=Number(el.dataset.z);SK.layer(el,z,{fill:z>-100?1.02:1.08,ox:960,oy:540});el.style.filter='blur('+el.dataset.blur+'px)';});"
    stepped=r['style'] in ['stop-motion','vox','mix-media']
    js=f'''(()=>{{const root=document.querySelector('[data-composition-id="{cid}"]');{helpers}{setup}SK.clip('{cid}',{{T:4,W:1920,H:1080,bg:'{bg}',update:raw=>{{const t={"SK.stepTime(raw,15)" if stepped else "raw"};{anim[key]}q('.rule').style.transform='scaleX('+E(t,0,.7)+')';qa('.meter i').forEach((el,j)=>el.style.opacity=t>=j*.5?1:.2);}}}});}})();'''
    markup=f'<div id="root" data-composition-id="{cid}" data-start="0" data-duration="4" data-width="1920" data-height="1080"><div class="sk-stage" style="background:{bg};color:{fg}"><div class="fill" style="background:{bg}"></div>{body[key]}{furniture}</div></div>'
    (P/r['source']).write_text(f'<!doctype html><html lang="en"><head><meta charset="UTF-8"/><title>{r["title"]}</title></head><body><template><style>{base}{style.get(key,"")}</style>{markup}<script>{js}</script></template></body></html>')
# HyperFrames 0.7.24 includes both ends of a mount interval. Exclude the
# outgoing cut instant without removing any 30/120 fps sample, and isolate
# descendant z-index values so they cannot paint into neighboring scenes.
mounts=''.join(f'<div id="mount-{i+1:02}" class="mount" style="z-index:{i}" data-layout-allow-overlap data-layout-allow-occlusion data-composition-id="{r["id"]}" data-composition-src="{r["source"]}" data-start="{i*4}" data-duration="{4 if i==len(rows)-1 else 3.999999}" data-track-index="1" data-width="1920" data-height="1080"></div>' for i,r in enumerate(rows))
host=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"/><title>ATELIER / Richer by Design</title><script src="vendor/gsap.min.js"></script><script src="vendor/motion-kit.js"></script><script src="vendor/style-kit.js"></script><link rel="stylesheet" href="assets/design.css"/><style>html,body{{margin:0;width:1920px;height:1080px;overflow:hidden;background:#171918}}#stage{{position:relative;width:1920px;height:1080px;overflow:hidden}}.mount{{position:absolute;inset:0;width:1920px;height:1080px;isolation:isolate}}audio.clip{{position:absolute;width:0;height:0;opacity:0}}</style></head><body><div id="stage" data-composition-id="style-atelier" data-start="0" data-duration="64" data-width="1920" data-height="1080" data-fps="30">{mounts}<audio id="master" class="clip" src="assets/audio/master.wav" data-start="0" data-duration="64" data-track-index="20" data-volume="1"></audio></div><script>window.__timelines=window.__timelines||{{}};window.__timelines['style-atelier']=gsap.timeline({{paused:true}});</script></body></html>'''
(P/'index.html').write_text(host)
print('Built sixteen editable studies and 64-second Atelier host')
